return {hdroom1801={id="hdroom1801",name="福来镖局",permission=1,mapHide="0",dsc="一处新开的镖局，听说是从附近迁过来的一家老字号，门面还算气派，来来往往不少人。",left="hdroom1818",right="hdroom1820",roomRoles={"rw01","rw02"},roomItems={},roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",0}},{type="inroom",args={"hdroom1801","any"}}}},autoResult1={{type="stop",args={}},{type="doc",args={"CYN王庚金好像有些话要说。NOR"}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318001",1}},{type="inroom",args={"hdroom1801","hdroom1820"}}}},autoResult2={{type="stop",args={}},{type="doc",args={"CYN先去库房看看吧。NOR"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom1802={id="hdroom1802",name="平安大街",permission=1,mapHide="0",dsc="新春清晨，朝露还未晞，朝阳还未完全升起，平安大街的人们个个都很有活力。街旁的车马行的生意变得异常火热，无论是本地镇民还是外地来客，纷纷在车马行停车下马卸货，随后又马不停蹄地赶往另外的街区，导致平安大街上一片拥挤。",left="hdroom1803",right="hdroom1819",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom1803={id="hdroom1803",name="小镇西口",permission=1,mapHide="0",dsc="一大清早，小镇村口早已人来人往：挑担赶路的，驾牛车送货的，赶着毛驴拉货车的，络绎不绝，齐齐赶向小镇的新春集会。无论是牛车还是驴车，上面都装满各式各样的年货，村民们你争我喊，似是要将自己的年货和别人的年货分个高低。",down="hdroom1804",right="hdroom1802",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCond